/**
 * Helper to parse launch parameters from PalmSystem or query strings
 */
function parseParamsString(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;
  try {
    var parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object') return parsed;
  } catch (_) {}
  try {
    var result = {};
    var pairs = String(raw).split('&');
    for (var i = 0; i < pairs.length; i++) {
      if (!pairs[i]) continue;
      var eqIdx = pairs[i].indexOf('=');
      if (eqIdx !== -1) {
        var key = decodeURIComponent(pairs[i].substring(0, eqIdx));
        var val = decodeURIComponent(pairs[i].substring(eqIdx + 1));
        if (key) result[key] = val;
      } else {
        var keyOnly = decodeURIComponent(pairs[i]);
        if (keyOnly) result[keyOnly] = '';
      }
    }
    return result;
  } catch (_) {
    return {};
  }
}

/**
 * Resolves active launch parameters from PalmSystem, query string, or localStorage
 * Prioritized cascade:
 * 1. launchParams.proxyUrl (PalmSystem)
 * 2. URL query ?proxyUrl=
 * 3. localStorage.getItem('cinejoy_proxy_url')
 * 4. Default: 'http://127.0.0.1:8088'
 */
function getActiveLaunchParams() {
  var params = {};
  var palmParams = {};
  var urlParams = {};
  var savedProxy = null;

  if (typeof window !== 'undefined') {
    // 1. webOS PalmSystem launch parameters (highest priority)
    if (window.PalmSystem && window.PalmSystem.launchParams) {
      palmParams = parseParamsString(window.PalmSystem.launchParams);
    }

    // 2. URL query string (?proxyUrl=...) fallback
    if (window.location && window.location.search) {
      try {
        var qs = window.location.search.replace(/^\?/, '');
        urlParams = parseParamsString(qs);
      } catch (_) {}
    }

    // 3. Persistent in-app settings
    try {
      if (window.localStorage) {
        savedProxy = window.localStorage.getItem('cinejoy_proxy_url');
      }
    } catch (_) {}

    // Base query params
    for (var q in urlParams) {
      if (Object.prototype.hasOwnProperty.call(urlParams, q)) {
        params[q] = urlParams[q];
      }
    }

    // PalmSystem launch parameters take absolute precedence over URL query parameters
    for (var k in palmParams) {
      if (Object.prototype.hasOwnProperty.call(palmParams, k)) {
        params[k] = palmParams[k];
      }
    }

    // Exact prioritized cascade in resolving proxyBaseUrl:
    // launchParams.proxyUrl > URL query ?proxyUrl= > localStorage.getItem('cinejoy_proxy_url') > default 'http://127.0.0.1:8088'
    var resolvedProxyUrl = null;
    var hasExplicitOverride = false;
    var proxySource = 'default';

    if (palmParams && palmParams.proxyUrl) {
      resolvedProxyUrl = palmParams.proxyUrl;
      hasExplicitOverride = true;
      proxySource = 'launchParams';
    } else if (urlParams && urlParams.proxyUrl) {
      resolvedProxyUrl = urlParams.proxyUrl;
      hasExplicitOverride = true;
      proxySource = 'query';
    } else if (savedProxy) {
      resolvedProxyUrl = savedProxy;
      hasExplicitOverride = false;
      proxySource = 'localStorage';
    } else {
      resolvedProxyUrl = 'http://127.0.0.1:8088';
      hasExplicitOverride = false;
      proxySource = 'default';
    }

    params.proxyUrl = resolvedProxyUrl;
    CINEJOY_CONFIG.proxyBaseUrl = resolvedProxyUrl;
    CINEJOY_CONFIG.hasExplicitProxyOverride = hasExplicitOverride;
    CINEJOY_CONFIG.proxySource = proxySource;
  } else {
    // Node.js test environment fallback
    CINEJOY_CONFIG.proxyBaseUrl = CINEJOY_CONFIG.proxyBaseUrl || 'http://127.0.0.1:8088';
    CINEJOY_CONFIG.hasExplicitProxyOverride = false;
    CINEJOY_CONFIG.proxySource = 'default';
    params.proxyUrl = CINEJOY_CONFIG.proxyBaseUrl;
  }

  return params;
}

// Auto-apply proxyUrl if passed via launchParams or query string
var initialParams = getActiveLaunchParams();
if (initialParams.proxyUrl) {
  CINEJOY_CONFIG.proxyBaseUrl = initialParams.proxyUrl;
}

