// Current Application State
state: {
  initialized: false,
  currentView: 'home',
  previousView: null,
  detailsOriginView: null,
  searchQuery: '',
  activeDetailItem: null,
  focusedElement: null,
  lunaSubscribed: false,
  activeProxyPort: 8088,
  lunaBridge: null,
  lunaRequest: null,
  lunaUptime: null
},

// View Registry
views: ['home', 'movies', 'series', 'search', 'details', 'player'],

/**
 * Initialize application on DOM ready
 */
init: function () {
  if (this.state.initialized) {
    return;
  }
  this.state.initialized = true;
  console.log('[CinejoyApp] Initializing 10-foot TV application shell...');

  var self = this;
  if (typeof window !== 'undefined' && window.SpatialNav) {
    window.SpatialNav.init({
      onBack: function () {
        return self.handleBackNavigation();
      },
      onSelect: function (element) {
        if (element && typeof element.click === 'function') {
          element.click();
        }
      },
      onMediaKey: function (data) {
        self.handleMediaKey(data.action);
      },
      onColorKey: function (data) {
        self.handleColorKey(data.color);
      }
    });

    window.SpatialNav.on('focus', function (data) {
      if (data && data.element) {
        self.state.focusedElement = data.element;
      }
    });
  }

  this.applyLaunchParams();
  this.initLunaKeepalive();

  this.bindEvents();
  this.initRouting();
  this.initKeyboard();
  this.setInitialFocus();
  console.log('[CinejoyApp] Application shell initialized successfully.');
},

