/**
 * Ingest launchParams from window.PalmSystem or query string
 */
applyLaunchParams: function (customParams) {
  var params = customParams;
  if (!params) {
    if (typeof window !== 'undefined' && window.CINEJOY_CONFIG && typeof window.CINEJOY_CONFIG.getLaunchParams === 'function') {
      params = window.CINEJOY_CONFIG.getLaunchParams();
    } else {
      params = {};
      if (typeof window !== 'undefined' && window.PalmSystem && window.PalmSystem.launchParams) {
        try {
          params = typeof window.PalmSystem.launchParams === 'string'
            ? JSON.parse(window.PalmSystem.launchParams)
            : window.PalmSystem.launchParams;
        } catch (_) {}
      }
    }
  }

  if (params && params.proxyUrl) {
    if (typeof window !== 'undefined' && window.CINEJOY_CONFIG) {
      window.CINEJOY_CONFIG.proxyBaseUrl = params.proxyUrl;
    }
    if (typeof global !== 'undefined' && global.CINEJOY_CONFIG) {
      global.CINEJOY_CONFIG.proxyBaseUrl = params.proxyUrl;
    }
    var isExplicit = !!(typeof window !== 'undefined' && window.CINEJOY_CONFIG && window.CINEJOY_CONFIG.hasExplicitProxyOverride);
    if (isExplicit && typeof window !== 'undefined' && window.PlayerController) {
      window.PlayerController._customProxyBaseUrl = params.proxyUrl;
    }
    console.log('[CinejoyApp] Active proxyBaseUrl configured to: ' + params.proxyUrl + (isExplicit ? ' (explicit override)' : ''));
  }
  return params;
},

/**
 * Auto-spawn and maintain Luna keepalive subscription hook
 * Supports:
 * 1. webOSTV.service.request / window.webOS.service.request
 * 2. window.PalmServiceBridge || window.WebOSServiceBridge
 * Maintains persistent subscription to keep on-device proxy daemon alive (Triple-Shield)
 */
initLunaKeepalive: function () {
  var self = this;
  var serviceUri = 'luna://com.cinejoy.tv.service';
  var method = 'keepalive';

  // Clear any pending reconnection timer
  if (this._lunaReconnectTimer) {
    clearTimeout(this._lunaReconnectTimer);
    this._lunaReconnectTimer = null;
  }

  // Method 1: webOSTV.service.request / window.webOS.service.request if available
  var serviceApi = null;
  if (typeof window !== 'undefined') {
    if (window.webOSTV && window.webOSTV.service && typeof window.webOSTV.service.request === 'function') {
      serviceApi = window.webOSTV.service;
    } else if (window.webOS && window.webOS.service && typeof window.webOS.service.request === 'function') {
      serviceApi = window.webOS.service;
    }
  }

  if (serviceApi) {
    try {
      console.log('[CinejoyApp] Registering Luna keepalive via webOSTV.service.request...');
      var req = serviceApi.request(serviceUri, {
        method: method,
        parameters: { subscribe: true },
        subscribe: true,
        resubscribe: true,
        onSuccess: function (res) {
          self.handleKeepaliveSuccess(res);
        },
        onFailure: function (err) {
          self.handleKeepaliveFailure(err);
        }
      });
      this.state.lunaRequest = req;
      return req;
    } catch (err) {
      console.warn('[CinejoyApp] webOSTV.service.request call error:', err);
      this.handleKeepaliveFailure(err);
      return null;
    }
  }

  // Method 2: Direct native PalmServiceBridge or WebOSServiceBridge (webOS Chromium WAM)
  var Bridge = (typeof window !== 'undefined' && (window.PalmServiceBridge || window.WebOSServiceBridge)) || null;
  if (Bridge) {
    try {
      console.log('[CinejoyApp] Registering Luna keepalive via native PalmServiceBridge / WebOSServiceBridge...');
      var bridge = new Bridge();
      bridge.onservicecallback = function (msg) {
        try {
          var res = typeof msg === 'string' ? JSON.parse(msg) : msg;
          if (res && res.returnValue !== false) {
            self.handleKeepaliveSuccess(res);
          } else {
            self.handleKeepaliveFailure(res);
          }
        } catch (e) {
          console.warn('[CinejoyApp] Native bridge payload parse error:', e);
          self.handleKeepaliveFailure(e);
        }
      };

      bridge.call(serviceUri + '/' + method, JSON.stringify({ subscribe: true }));

      // Store on window and app state to prevent garbage collection of IPC socket
      if (typeof window !== 'undefined') {
        window._cinejoyLunaBridge = bridge;
      }
      this.state.lunaBridge = bridge;
      return bridge;
    } catch (err) {
      console.warn('[CinejoyApp] Native PalmServiceBridge instantiation/call error:', err);
      this.handleKeepaliveFailure(err);
      return null;
    }
  }

  // Method 3: Desktop Browser / Node test environment fallback
  console.log('[CinejoyApp] Running in standard browser or Node test environment (PalmServiceBridge unavailable).');
  return null;
},

/**
 * Backward-compatible alias for probeLunaService
 */
probeLunaService: function () {
  return this.initLunaKeepalive();
},

/**
 * Handler for successful keepalive responses
 * Updates dynamic port if not explicitly overridden
 */
handleKeepaliveSuccess: function (res) {
  this.state.lunaSubscribed = true;
  this.state.lunaUptime = res && res.uptime;
  console.log('[CinejoyApp] Luna keepalive subscription active (uptime: ' + (res && res.uptime) + 's)');

  // Reset reconnect backoff
  this._lunaReconnectDelay = 1000;
  if (this._lunaReconnectTimer) {
    clearTimeout(this._lunaReconnectTimer);
    this._lunaReconnectTimer = null;
  }

  // Handle dynamic port assignment (e.g. 8088, 8089 on port collision)
  if (res && typeof res.port === 'number' && res.port > 0) {
    var port = res.port;
    this.state.activeProxyPort = port;

    var hasExplicitOverride = false;
    if (typeof window !== 'undefined' && window.CINEJOY_CONFIG) {
      hasExplicitOverride = !!window.CINEJOY_CONFIG.hasExplicitProxyOverride;
    }

    if (!hasExplicitOverride) {
      var newProxyUrl = 'http://127.0.0.1:' + port;
      if (typeof window !== 'undefined') {
        if (window.CINEJOY_CONFIG) {
          window.CINEJOY_CONFIG.proxyBaseUrl = newProxyUrl;
          if (typeof window.CINEJOY_CONFIG.setProxyUrl === 'function') {
            window.CINEJOY_CONFIG.setProxyUrl(newProxyUrl);
          }
        }
        if (window.PlayerController) {
          window.PlayerController._customProxyBaseUrl = newProxyUrl;
        }
      }
      if (typeof global !== 'undefined' && global.CINEJOY_CONFIG) {
        global.CINEJOY_CONFIG.proxyBaseUrl = newProxyUrl;
      }
      console.log('[CinejoyApp] Dynamic proxy port updated to: ' + port + ' (' + newProxyUrl + ')');
    } else {
      console.log('[CinejoyApp] Explicit proxy override active; preserving override: ' + (window.CINEJOY_CONFIG && window.CINEJOY_CONFIG.proxyBaseUrl));
    }
  }
},

/**
 * Handler for keepalive failure or disconnection
 * Schedules automatic reconnect with exponential backoff
 */
handleKeepaliveFailure: function (err) {
  this.state.lunaSubscribed = false;
  console.warn('[CinejoyApp] Luna keepalive subscription failed or disconnected:', err);

  var self = this;
  if (!this._lunaReconnectDelay) {
    this._lunaReconnectDelay = 1000;
  }

  if (this._lunaReconnectTimer) {
    clearTimeout(this._lunaReconnectTimer);
  }

  this._lunaReconnectTimer = setTimeout(function () {
    self._lunaReconnectTimer = null;
    self._lunaReconnectDelay = Math.min(self._lunaReconnectDelay * 1.5, 10000);
    console.log('[CinejoyApp] Attempting Luna keepalive reconnection...');
    self.initLunaKeepalive();
  }, this._lunaReconnectDelay);
},

