/**
 * tests/test-prod2-keepalive.js
 * Milestone Prod-2: Luna Keepalive Hook, Dynamic Port Resolution & Priority Cascade Tests
 * 
 * Target device: LG 32LR686BPSA (webOS 8.5.0, Chromium ~108 WAM)
 * 
 * Verifies:
 * 1. Exact Prioritized Cascade in resolving proxyBaseUrl:
 *    - Scenario 1: launchParams.proxyUrl > URL query > localStorage > default (Fixes priority inversion)
 *    - Scenario 2: URL query ?proxyUrl= > localStorage > default
 *    - Scenario 3: localStorage.getItem('cinejoy_proxy_url') > default
 *    - Scenario 4: Default fallback ('http://127.0.0.1:8088')
 * 2. PalmSystem.launchParams format parsing (JSON string, raw object, query-string key/val)
 * 3. Keepalive Subscription Registration:
 *    - Native window.PalmServiceBridge
 *    - Native window.WebOSServiceBridge
 *    - window.webOSTV.service.request / window.webOS.service.request
 *    - Retention in window._cinejoyLunaBridge to prevent GC socket teardown
 *    - Graceful fallback when no bridge is present (browser/Node)
 * 4. Dynamic Port Updating:
 *    - Dynamic port response ({ returnValue: true, port: 8089 }) updates CINEJOY_CONFIG.proxyBaseUrl
 *    - Updates PlayerController._customProxyBaseUrl and CinejoyApp.state.activeProxyPort
 *    - Explicit overrides (launchParams or query) strictly preserved against dynamic port updates
 * 5. Disconnection & Auto-Reconnection:
 *    - Disconnection sets state.lunaSubscribed = false and schedules auto-reconnection
 * 6. Stream Resolution & View Routing:
 *    - PlayerController._fetchStreamResolution queries the dynamically resolved proxyBaseUrl
 */

'use strict';

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      throw new Error('JSDOM module could not be resolved: ' + e1.message);
    }
  }
}

const ROOT_DIR = path.resolve(__dirname, '..');

// ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;

async function check(id, description, fn) {
  totalChecks++;
  const label = `[Prod-2] [${id}] ${description}`;
  try {
    await fn();
    passedChecks++;
    console.log(`  ${C.green}✔ PASS${C.reset} ${label}`);
  } catch (err) {
    failedChecks++;
    console.error(`  ${C.red}✖ FAIL${C.reset} ${label}`);
    console.error(`      ${C.red}${err.stack || err.message}${C.reset}`);
  }
}

/**
 * Creates an isolated test harness loading production HTML and scripts
 */
function createHarness(options = {}) {
  const htmlPath = path.resolve(ROOT_DIR, 'app/index.html');
  const configPath = path.resolve(ROOT_DIR, 'app/js/config.js');
  const navPath = path.resolve(ROOT_DIR, 'app/js/navigation.js');
  const tmdbPath = path.resolve(ROOT_DIR, 'app/js/tmdb.js');
  const homePath = path.resolve(ROOT_DIR, 'app/js/views/home.js');
  const catalogPath = path.resolve(ROOT_DIR, 'app/js/views/catalog.js');
  const searchPath = path.resolve(ROOT_DIR, 'app/js/views/search.js');
  const detailsPath = path.resolve(ROOT_DIR, 'app/js/views/details.js');
  const playerPath = path.resolve(ROOT_DIR, 'app/js/player.js');
  const appPath = path.resolve(ROOT_DIR, 'app/js/app.js');

  const url = options.url || 'http://127.0.0.1:8088/#home';
  const html = fs.readFileSync(htmlPath, 'utf8');

  const dom = new JSDOM(html, {
    url: url,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  // Mock localStorage
  const storage = options.localStorage || {};
  window.localStorage = {
    getItem: (key) => (Object.prototype.hasOwnProperty.call(storage, key) ? storage[key] : null),
    setItem: (key, val) => { storage[key] = String(val); },
    removeItem: (key) => { delete storage[key]; },
    clear: () => { for (const k in storage) delete storage[k]; }
  };

  // Mock PalmSystem if provided
  if (options.palmSystem) {
    window.PalmSystem = options.palmSystem;
  }

  // Mock PalmServiceBridge if requested
  if (options.mockPalmBridge) {
    window.PalmServiceBridge = options.mockPalmBridge;
  }
  if (options.mockWebOSBridge) {
    window.WebOSServiceBridge = options.mockWebOSBridge;
  }

  // Mock webOSTV if requested
  if (options.mockWebOSTV) {
    window.webOSTV = options.mockWebOSTV;
  }
  if (options.mockWebOS) {
    window.webOS = options.mockWebOS;
  }

  // Load scripts in production order
  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(tmdbPath, 'utf8'));
  window.eval(fs.readFileSync(homePath, 'utf8'));
  window.eval(fs.readFileSync(catalogPath, 'utf8'));
  window.eval(fs.readFileSync(searchPath, 'utf8'));
  window.eval(fs.readFileSync(detailsPath, 'utf8'));
  window.eval(fs.readFileSync(playerPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  if (!options.skipAppInit) {
    window.CinejoyApp.init();
  }

  return {
    dom,
    window,
    document: window.document,
    config: window.CINEJOY_CONFIG,
    app: window.CinejoyApp,
    player: window.PlayerController,
    nav: window.SpatialNav
  };
}

async function runProd2KeepaliveTests() {
  console.log(`\n${C.bold}${C.cyan}================================================================================${C.reset}`);
  console.log(`${C.bold}► MILESTONE PROD-2: FRONTEND KEEPALIVE & DYNAMIC CONFIG CASCADE TESTS${C.reset}`);
  console.log(`${C.cyan}================================================================================${C.reset}\n`);

  // =========================================================================
  // Section 1: Config Cascade Priorities (All 4 Scenarios)
  // =========================================================================

  await check('C1.1', 'Scenario 1: launchParams.proxyUrl takes precedence over URL query, localStorage and default (Fix priority inversion)', () => {
    const { window, config } = createHarness({
      palmSystem: {
        launchParams: JSON.stringify({ proxyUrl: 'http://192.168.1.55:8088' })
      },
      url: 'http://127.0.0.1:8088/?proxyUrl=http://192.168.1.99:8088#home',
      localStorage: {
        cinejoy_proxy_url: 'http://192.168.1.77:8088'
      }
    });

    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.55:8088', 'launchParams.proxyUrl must win over URL query and localStorage');
    assert.strictEqual(config.proxySource, 'launchParams', 'proxySource must be launchParams');
    assert.strictEqual(config.hasExplicitProxyOverride, true, 'hasExplicitProxyOverride must be true');
    assert.strictEqual(window.PlayerController._customProxyBaseUrl, 'http://192.168.1.55:8088', 'PlayerController custom proxy base URL must match');
  });

  await check('C1.2', 'Scenario 1b: launchParams formatted as raw object', () => {
    const { config } = createHarness({
      palmSystem: {
        launchParams: { proxyUrl: 'http://192.168.1.60:8088' }
      },
      url: 'http://127.0.0.1:8088/?proxyUrl=http://ignored:8088#home'
    });

    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.60:8088', 'Object launchParams must be ingested');
    assert.strictEqual(config.hasExplicitProxyOverride, true);
  });

  await check('C1.3', 'Scenario 1c: launchParams formatted as URL query string format ("proxyUrl=...")', () => {
    const { config } = createHarness({
      palmSystem: {
        launchParams: 'proxyUrl=http://192.168.1.65:8088&other=val'
      },
      url: 'http://127.0.0.1:8088/?proxyUrl=http://ignored:8088#home'
    });

    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.65:8088', 'Query-string formatted launchParams must be parsed');
    assert.strictEqual(config.hasExplicitProxyOverride, true);
  });

  await check('C1.4', 'Scenario 2: URL query ?proxyUrl= takes precedence when no launchParams.proxyUrl', () => {
    const { config, window } = createHarness({
      url: 'http://127.0.0.1:8088/?proxyUrl=http://192.168.1.99:8088#home',
      localStorage: {
        cinejoy_proxy_url: 'http://192.168.1.77:8088'
      }
    });

    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.99:8088', 'URL query must take precedence over localStorage');
    assert.strictEqual(config.proxySource, 'query', 'proxySource must be query');
    assert.strictEqual(config.hasExplicitProxyOverride, true, 'hasExplicitProxyOverride must be true for query param');
    assert.strictEqual(window.PlayerController._customProxyBaseUrl, 'http://192.168.1.99:8088');
  });

  await check('C1.5', 'Scenario 3: localStorage takes precedence when no launchParams and no URL query', () => {
    const { config } = createHarness({
      url: 'http://127.0.0.1:8088/#home',
      localStorage: {
        cinejoy_proxy_url: 'http://192.168.1.77:8088'
      }
    });

    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.77:8088', 'localStorage must take precedence over default');
    assert.strictEqual(config.proxySource, 'localStorage', 'proxySource must be localStorage');
    assert.strictEqual(config.hasExplicitProxyOverride, false, 'localStorage is not an explicit session override');
  });

  await check('C1.6', 'Scenario 4: Default fallback is strictly http://127.0.0.1:8088', () => {
    const { config, window } = createHarness({
      url: 'http://127.0.0.1:8088/#home'
    });

    assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088', 'Default must be http://127.0.0.1:8088');
    assert.strictEqual(config.proxySource, 'default', 'proxySource must be default');
    assert.strictEqual(config.hasExplicitProxyOverride, false, 'hasExplicitProxyOverride must be false');
    assert.strictEqual(window.PlayerController._customProxyBaseUrl, undefined, 'PlayerController custom proxy should not be hardcoded to override keepalive');
  });

  // =========================================================================
  // Section 2: Keepalive Subscription Registration
  // =========================================================================

  await check('K2.1', 'Native PalmServiceBridge keepalive subscription hook registers on app.init', () => {
    let bridgeInstantiated = false;
    let registeredUri = null;
    let registeredParams = null;
    let bridgeInstance = null;

    function MockPalmBridge() {
      bridgeInstantiated = true;
      bridgeInstance = this;
      this.call = function (uri, params) {
        registeredUri = uri;
        registeredParams = params;
      };
    }

    const { window, app } = createHarness({
      mockPalmBridge: MockPalmBridge
    });

    assert.strictEqual(bridgeInstantiated, true, 'PalmServiceBridge must be instantiated');
    assert.strictEqual(registeredUri, 'luna://com.cinejoy.tv.service/keepalive', 'Must call luna://com.cinejoy.tv.service/keepalive');
    assert.deepStrictEqual(JSON.parse(registeredParams), { subscribe: true }, 'Must request subscribe: true');
    assert.strictEqual(window._cinejoyLunaBridge, bridgeInstance, 'Bridge must be retained on window._cinejoyLunaBridge to prevent GC');
    assert.strictEqual(app.state.lunaBridge, bridgeInstance, 'Bridge must be saved on CinejoyApp.state.lunaBridge');
  });

  await check('K2.2', 'Native WebOSServiceBridge keepalive subscription hook registers when PalmServiceBridge is undefined', () => {
    let bridgeInstantiated = false;
    let registeredUri = null;
    let registeredParams = null;

    function MockWebOSBridge() {
      bridgeInstantiated = true;
      this.call = function (uri, params) {
        registeredUri = uri;
        registeredParams = params;
      };
    }

    const { app } = createHarness({
      mockWebOSBridge: MockWebOSBridge
    });

    assert.strictEqual(bridgeInstantiated, true, 'WebOSServiceBridge must be instantiated');
    assert.strictEqual(registeredUri, 'luna://com.cinejoy.tv.service/keepalive');
    assert.deepStrictEqual(JSON.parse(registeredParams), { subscribe: true });
    assert.ok(app.state.lunaBridge, 'state.lunaBridge must be assigned');
  });

  await check('K2.3', 'webOSTV.service.request keepalive subscription registers if webOSTV is present', () => {
    let requestCalled = false;
    let targetUri = null;
    let requestOptions = null;

    const mockWebOSTV = {
      service: {
        request: function (uri, opts) {
          requestCalled = true;
          targetUri = uri;
          requestOptions = opts;
          return { cancel: () => {} };
        }
      }
    };

    const { app } = createHarness({
      mockWebOSTV: mockWebOSTV
    });

    assert.strictEqual(requestCalled, true, 'webOSTV.service.request must be called');
    assert.strictEqual(targetUri, 'luna://com.cinejoy.tv.service');
    assert.strictEqual(requestOptions.method, 'keepalive');
    assert.strictEqual(requestOptions.subscribe, true);
    assert.deepStrictEqual(requestOptions.parameters, { subscribe: true });
    assert.ok(app.state.lunaRequest, 'state.lunaRequest must be tracked');
  });

  await check('K2.4', 'Graceful fallback when neither Luna bridge is present', () => {
    const { app } = createHarness();
    assert.strictEqual(app.state.lunaSubscribed, false, 'lunaSubscribed should be false');
    assert.strictEqual(app.state.lunaBridge, null, 'lunaBridge should be null');
  });

  // =========================================================================
  // Section 3: Dynamic Port Updating
  // =========================================================================

  await check('P3.1', 'Keepalive response dynamically updates proxyBaseUrl to port 8089 when no explicit override', () => {
    let bridgeInstance = null;

    function MockPalmBridge() {
      bridgeInstance = this;
      this.call = function () {};
    }

    const { window, config, app } = createHarness({
      mockPalmBridge: MockPalmBridge
    });

    assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088', 'Starts at default 8088');

    // Simulate keepalive response with fallback port 8089 (port collision)
    bridgeInstance.onservicecallback(JSON.stringify({
      returnValue: true,
      status: 'subscribed',
      port: 8089,
      uptime: 42.5
    }));

    assert.strictEqual(app.state.lunaSubscribed, true, 'lunaSubscribed must be true');
    assert.strictEqual(app.state.activeProxyPort, 8089, 'activeProxyPort must be updated to 8089');
    assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8089', 'config.proxyBaseUrl must dynamically update to port 8089');
    assert.strictEqual(window.PlayerController._customProxyBaseUrl, 'http://127.0.0.1:8089', 'PlayerController custom proxy URL must be updated to port 8089');
  });

  await check('P3.2', 'Explicit launchParams override strictly preserves configured proxyUrl against dynamic port updates', () => {
    let bridgeInstance = null;

    function MockPalmBridge() {
      bridgeInstance = this;
      this.call = function () {};
    }

    const { window, config, app } = createHarness({
      palmSystem: {
        launchParams: JSON.stringify({ proxyUrl: 'http://192.168.1.6:8088' })
      },
      mockPalmBridge: MockPalmBridge
    });

    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.6:8088', 'Config starts with explicit launchParams override');
    assert.strictEqual(config.hasExplicitProxyOverride, true);

    // Simulate keepalive response with port 8089
    bridgeInstance.onservicecallback(JSON.stringify({
      returnValue: true,
      status: 'subscribed',
      port: 8089,
      uptime: 10
    }));

    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.6:8088', 'Explicit override must NOT be overwritten by dynamic port update');
    assert.strictEqual(window.PlayerController._customProxyBaseUrl, 'http://192.168.1.6:8088', 'PlayerController proxy must also preserve explicit override');
    assert.strictEqual(app.state.lunaSubscribed, true);
    assert.strictEqual(app.state.activeProxyPort, 8089, 'activeProxyPort tracks on-device service port');
  });

  await check('P3.3', 'Explicit URL query override strictly preserves configured proxyUrl against dynamic port updates', () => {
    let bridgeInstance = null;

    function MockPalmBridge() {
      bridgeInstance = this;
      this.call = function () {};
    }

    const { window, config } = createHarness({
      url: 'http://127.0.0.1:8088/?proxyUrl=http://192.168.1.100:8088#home',
      mockPalmBridge: MockPalmBridge
    });

    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.100:8088');
    assert.strictEqual(config.hasExplicitProxyOverride, true);

    // Simulate keepalive response with port 8090
    bridgeInstance.onservicecallback(JSON.stringify({
      returnValue: true,
      status: 'subscribed',
      port: 8090,
      uptime: 25
    }));

    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.100:8088', 'URL query explicit override must be preserved');
    assert.strictEqual(window.PlayerController._customProxyBaseUrl, 'http://192.168.1.100:8088');
  });

  // =========================================================================
  // Section 4: Disconnection & Auto-Reconnection
  // =========================================================================

  await check('R4.1', 'Keepalive failure or disconnect updates state and schedules automatic reconnection', () => {
    let callCount = 0;
    let bridgeInstance = null;

    function MockPalmBridge() {
      bridgeInstance = this;
      this.call = function () {
        callCount++;
      };
    }

    const { app } = createHarness({
      mockPalmBridge: MockPalmBridge
    });

    assert.strictEqual(callCount, 1, 'Initial call on bootstrap');

    // First succeed
    bridgeInstance.onservicecallback(JSON.stringify({
      returnValue: true,
      port: 8088,
      uptime: 10
    }));
    assert.strictEqual(app.state.lunaSubscribed, true);

    // Now simulate failure / service crash
    bridgeInstance.onservicecallback(JSON.stringify({
      returnValue: false,
      errorCode: -1,
      errorText: 'Service daemon died'
    }));

    assert.strictEqual(app.state.lunaSubscribed, false, 'State must reflect disconnected status');
    assert.ok(app._lunaReconnectTimer, 'A reconnection timer must be active');

    // Trigger timer callback directly to verify reconnect call
    clearTimeout(app._lunaReconnectTimer);
    app._lunaReconnectTimer = null;
    app.initLunaKeepalive();

    assert.strictEqual(callCount, 2, 'Must have re-attempted connection to keepalive service');
  });

  // =========================================================================
  // Section 5: End-to-End Stream Resolution & View Routing
  // =========================================================================

  await check('V5.1', 'PlayerController constructs stream resolution request through active proxyBaseUrl', () => {
    let bridgeInstance = null;

    function MockPalmBridge() {
      bridgeInstance = this;
      this.call = function () {};
    }

    const { player, config } = createHarness({
      mockPalmBridge: MockPalmBridge
    });

    // Simulate keepalive reporting fallback port 8089
    bridgeInstance.onservicecallback(JSON.stringify({
      returnValue: true,
      port: 8089,
      uptime: 15
    }));

    assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8089');

    // Intercept fetch inside PlayerController
    let fetchedUrl = null;
    player._fetchWithTimeout = function (url) {
      fetchedUrl = url;
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ success: true, streamUrl: 'http://127.0.0.1:8089/hls/proxy?url=test' })
      });
    };

    player._fetchStreamResolution({ id: 550, title: 'Fight Club', type: 'movie' }, 'Cinejoy-Fast');
    assert.ok(fetchedUrl, 'Stream resolution fetch must be initiated');
    assert.ok(fetchedUrl.startsWith('http://127.0.0.1:8089/api/stream?'), `Stream resolution must route to dynamic port: ${fetchedUrl}`);
  });

  await check('V5.2', 'Details and Catalog view switches delegate content payload to player view cleanly', () => {
    const { app, document } = createHarness();

    // Verify view switching to player
    app.switchView('player', {
      tmdbId: 101,
      type: 'movie',
      title: 'Inception'
    });

    assert.strictEqual(app.state.currentView, 'player', 'View must switch to player');
    const playerView = document.getElementById('view-player');
    assert.ok(playerView.classList.contains('active'), 'Player view container must have active class');
  });

  // =========================================================================
  // Summary & Verification Verdict
  // =========================================================================

  console.log(`\n${C.bold}${C.cyan}------------------------------------------------------------------------${C.reset}`);
  console.log(`  Prod-2 Keepalive Checks Completed: ${totalChecks}`);
  console.log(`  Passed Checks:                     ${C.green}${C.bold}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:                     ${failedChecks > 0 ? `${C.red}${C.bold}${failedChecks}` : '0'}${C.reset}`);
  console.log(`${C.cyan}------------------------------------------------------------------------${C.reset}\n`);

  if (failedChecks > 0 || totalChecks < 14) {
    console.error(`${C.red}${C.bold}VERDICT: PROD-2 KEEPALIVE SUITE FAILED (${failedChecks} failures, ${totalChecks}/14 checks)${C.reset}\n`);
    process.exit(1);
  } else {
    console.log(`${C.green}${C.bold}VERDICT: PROD-2 KEEPALIVE SUITE PASSED (14/14 checks 100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  }
}

