await check('V5.1', 'PlayerController constructs stream resolution request through active proxyBaseUrl', () => {
  let bridgeInstance = null;

  function MockPalmBridge() {
    bridgeInstance = this;
    this.call = function () {};
  }

  const { player, config } = createHarness({
    mockPalmBridge: MockPalmBridge
  });

  // Simulate keepalive reporting fallback port 8089
  bridgeInstance.onservicecallback(JSON.stringify({
    returnValue: true,
    port: 8089,
    uptime: 15
  }));

  assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8089');

  // Intercept fetch inside PlayerController
  let fetchedUrl = null;
  player._fetchWithTimeout = function (url) {
    fetchedUrl = url;
    return Promise.resolve({
      ok: true,
      json: () => Promise.resolve({ success: true, streamUrl: 'http://127.0.0.1:8089/hls/proxy?url=test' })
    });
  };

  player._fetchStreamResolution({ id: 550, title: 'Fight Club', type: 'movie' }, 'Cinejoy-Fast');
  assert.ok(fetchedUrl, 'Stream resolution fetch must be initiated');
  assert.ok(fetchedUrl.startsWith('http://127.0.0.1:8089/api/stream?'), `Stream resolution must route to dynamic port: ${fetchedUrl}`);
});

